PREFIX brick: <http://brickschema.org/schema/1.0/bricks#>
PREFIX ref: <https://example.org/ref#>
SELECT ?zone ?zoneName ?point ?tsid WHERE {
  ?zone a brick:Zone .
  ?zone brick:hasSubEntity* ?point OPTIONAL {
  ?zone rdfs:label ?zoneName .
  ?zone ref:hasTimeseriesId ?zts .
  }
  ?point a brick:AirTemperatureSensor ; a brick:AirTemperature .
  ?point ref:hasTimeseriesId ?tsid .
}

